import React from "react";

const Home = () => (
  <div className="bg-gradient-to-b from-blue-500 to-blue-800 min-h-screen text-white flex flex-col justify-center items-center">
    <h1 className="text-6xl font-bold mb-8">MOOVVIEW</h1>
    <p className="text-xl mb-8">Recognize and analyze cattle breeds with ease.</p>
    <button className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded">
      Get Started
    </button>
  </div>
);

export default Home;
